        box(3, 0.05, 1.2, stripeMat, rx - ROAD_HALF - 1, 0.03, rz + i * 2.4, scene);
        box(3, 0.05, 1.2, stripeMat, rx + ROAD_HALF + 1, 0.03, rz + i * 2.4, scene);
      }
