  box(4.6, 0.3, 4.6, redMat, 20, 5.7, 162, scene);
  // Umbrellas: tilted pole + cone canopy, dotted along the sand.
  const umbrellaMat = new THREE.MeshLambertMaterial({ color: 0xe86a8c });
