      if (hasSave && S) {
        const jobs = S.stats ? (S.stats.missionsDone || 0) : 0;
        this.elTitleSaveInfo.textContent =
          'Saved game — Cash $' + Math.floor(S.cash || 0) +
          ' · Jobs done: ' + jobs +
          ' · Health: ' + Math.round(S.health || 0);
